class VkTurnFixChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static Application app;static MainWindow main;static ClientSession session;static int count;
 static void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static object Get(string name){return typeof(MainWindow).GetField(name,F).GetValue(main);}static object Call(string name,params object[] a){return typeof(MainWindow).GetMethod(name,F).Invoke(main,a);}
 static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}
 static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(20);while(!done()&&DateTime.UtcNow<end){Pump();Thread.Sleep(5);}if(!done())throw new Exception("Timeout");}static void Finish(Task t){Wait(()=>t.IsCompleted);t.GetAwaiter().GetResult();}
 static System.Collections.Generic.IEnumerable<T> All<T>(DependencyObject r)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(r);i++){var c=VisualTreeHelper.GetChild(r,i);if(c is T)yield return (T)c;foreach(var x in All<T>(c))yield return x;}}
 static T Dialog<T>(string title,Func<T> invoke,Action<Window> act){Exception error=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(s,e)=>{var w=app.Windows.Cast<Window>().FirstOrDefault(x=>x!=main&&x.Title==title);if(w==null)return;timer.Stop();try{w.Left=-10000;w.Top=-10000;w.UpdateLayout();act(w);}catch(Exception ex){error=ex;w.Close();}};timer.Start();try{var result=invoke();if(error!=null)throw error;return result;}finally{timer.Stop();}}
 static void Click(Window w,string text){All<Button>(w).Single(b=>Convert.ToString(b.Content)==text).RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}
 static void Save(FrameworkElement w,string file){w.UpdateLayout();var image=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(w);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(file))encoder.Save(stream);}
 static void Install(string id,string packages){var p=session.Core.Engines.Package(id);var staging=Path.Combine(session.Core.Engines.StorageRoot,".download-check-"+id);Directory.CreateDirectory(staging);session.Core.Engines.InstallArchive(p,Path.Combine(packages,Path.GetFileName(new Uri(p.Url).LocalPath)),staging,CancellationToken.None);}
 [STAThread]static int Main(string[] args){try{
  string root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("fresh root required");var program=typeof(MainWindow).Assembly.GetType("Mcrf.Wpf.Program");app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};program.GetMethod("LoadTheme",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{app});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());main=new MainWindow(new[]{"--data",root}){ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-10000,Top=-10000,Width=1050,Height=680};main.Show();Wait(()=>Get("session")!=null);session=(ClientSession)Get("session");((DispatcherTimer)Get("health")).Stop();typeof(ClientSession).GetField("catalogTask",F).SetValue(session,Task.FromResult(new ZapretStrategy[0]));
  if(args.Length>3&&args[3]=="layout"){LayoutOnly(root,args[2]);main.Close();Wait(()=>!main.IsVisible);app.Shutdown();Console.WriteLine("RESULT "+count+" layout checks PASS");return 0;}
  string hash=Convert.ToBase64String(Enumerable.Range(1,32).Select(i=>(byte)i).ToArray()).TrimEnd('=').Replace('+','-').Replace('/','_');string hashes=String.Join(",",Enumerable.Range(0,6).Select(i=>Convert.ToBase64String(Enumerable.Repeat((byte)(i+1),32).ToArray()).TrimEnd('=').Replace('+','-').Replace('/','_')));
  string wd="wdtt://connect?v=1&host=192.0.2.1&dtls=56002&wg=56004&local=9000&password=fixture&hashes="+Uri.EscapeDataString(hashes);var wdnode=Links.Read(wd).Single();Check(TurnProfile.Parse(wd).Hashes.Length==6,"WDTT percent-encoded comma hash list imports all six calls");
  string q=QwdttProfile.Link("fixture","192.0.2.1:56000","fixture","https://vk.ru/call/join/"+hash+"\nhttps://vk.com/call/join/"+hash);var qnode=Links.Read(q).Single();Check(QwdttProfile.Parse(q).Hashes.Length==1,"QWDTT newline VK URLs normalize and deduplicate");
  var cs=Links.Read("csqtt://connect?v=2&host=192.0.2.1&peer=56005&password=fixture&hashes="+hash).Single();cs.CsqttGeneration="2.1.5";
  var ids=CsqttGenerations.RequiredPackages(session.Core,new[]{cs});Check(ids.Length==2&&ids.Contains("csqtt-bridge")&&ids.Contains("csqtt215"),"CSQTT requires only its generation plus independent bridge, never WDTT");
  Check(CsqttGenerations.Get("2.1.9").Label.Contains("SWG 2.1")&&CsqttGenerations.Get("2.5").Label.Contains("SWG 2.5.1"),"SWG server versions visible in generation choices");
  Finish(Dialog("Дополнительные компоненты",()=>(Task<bool>)Call("DownloadCsqttRequirements",(object)new[]{cs},true),w=>{Check(All<TextBlock>(w).Any(t=>t.Text.Contains("Локальный IP-адаптер")),"CSQTT popup identifies standalone adapter");Click(w,"Добавить без скачивания");}));
  Finish(Dialog("Дополнительные компоненты",()=>(Task<bool>)Call("DownloadCsqttRequirements",(object)new[]{qnode},true),w=>{Check(All<TextBlock>(w).Any(t=>t.Text.Contains("QWDTT")),"QWDTT gets its own download popup after deferred CSQTT");Click(w,"Добавить без скачивания");}));
  Finish(Dialog("Дополнительные компоненты",()=>(Task)Call("ImportServerText",wd),w=>Click(w,"Добавить без скачивания")));Check(session.State.Servers.Any(n=>n.Protocol=="wdtt")&&(string)Get("current")=="Серверы","WDTT import persists and stays in servers when download deferred");
  session.State.Servers.Add(qnode);Call("Page","VK TURN");main.UpdateLayout();var sliders=All<Slider>(main).Where(v=>v.Name.StartsWith("vkStreams_")).ToArray();Check(sliders.Length==4&&sliders.All(v=>v.IsEnabled),"four usable stream sliders without installed engines");var cs25=sliders.Single(v=>v.Name=="vkStreams_csqtt25");cs25.Value=cs25.Maximum;Check(VkTurnSettings.Load(root).Streams["csqtt25"]==100,"CSQTT 2.5 slider persists selected worker count");
  var scroll=All<ScrollViewer>(main).Single(v=>v.Name=="vkTurnSettingsScroll");scroll.ScrollToBottom();main.UpdateLayout();Check(scroll.ScrollableHeight>0,"VK TURN all settings reachable in bounded scroll viewport");Save(main,Path.Combine(args[2],"vkturn-1050x680-bottom.png"));scroll.ScrollToTop();main.UpdateLayout();Save(main,Path.Combine(args[2],"vkturn-1050x680-top.png"));
  Dialog("VK TURN · "+qnode.Name,()=>{Call("VkTurnServerEditor",qnode);return true;},w=>{var mode=All<ComboBox>(w).Single(v=>v.Name=="vkQwdttMode");mode.SelectedIndex=2;var workers=All<Slider>(w).Single(v=>v.Name=="vkServerWorkers");workers.Value=2;Save(w,Path.Combine(args[2],"qwdtt-editor.png"));Click(w,"Сохранить");});Check(VkTurnSettings.Load(root).Servers[qnode.Id].QwdttMode=="raw","QWDTT editor persists RAW choice");Check(QwdttEngine.Mode(qnode,VkTurnSettings.Load(root))=="raw","runtime reads selected QWDTT transport");Check(CsqttGenerations.RequiredPackages(session.Core,new[]{qnode}).Contains("csqtt-bridge"),"RAW QWDTT requests standalone bridge");
  Install("csqtt-bridge",args[1]);Install("qwdtt",args[1]);Check(session.Core.CsqttBridgeExecutable!=null&&!session.Core.Engines.Installed("wdtt"),"standalone bridge verifies and installs with no WDTT package");Check(session.Core.HasEngine(qnode),"RAW QWDTT ready with QWDTT plus bridge only");
  var children=new System.Collections.Generic.List<System.Diagnostics.Process>();using(var raw=new System.Net.Sockets.UdpClient(0)){TurnEngines.StartRawBridge(session.Core.CsqttBridgeExecutable,((System.Net.IPEndPoint)raw.Client.LocalEndPoint).Port,"10.66.66.2","1.1.1.1",FreePort(),p=>children.Add(p),s=>{},CancellationToken.None);}Check(children.Count==1,"production runtime starts dedicated adapter, not WDTT");foreach(var p in children){p.StandardInput.Close();Check(p.WaitForExit(3000),"adapter exits on parent EOF without force kill");p.Dispose();}
  session.State.Mode="proxy";session.State.VpnEnabled=false;Call("QueueTunIntent",false);Finish((Task)Call("DrainTunIntent"));Check(((TextBlock)Get("status")).Text=="TUN отключён","successful OFF replaces stopping status with terminal state");Call("QueueTunIntent",true);Finish((Task)Call("DrainTunIntent"));Check(((TextBlock)Get("status")).Text.Contains("Сначала выберите"),"failed ON preserves error instead of pending or success state");
  Check(!session.Core.Running,"checks never started VPN or contacted real provider");main.Close();Wait(()=>!main.IsVisible);app.Shutdown();Console.WriteLine("RESULT "+count+" checks PASS");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);if(session!=null)session.Core.Stop();if(main!=null)main.Close();return 1;}}
 static void LayoutOnly(string root,string output){
  var q=Links.Read(QwdttProfile.Link("QWDTT fixture","192.0.2.1:56000","fixture",new string('A',43))).Single();session.State.Servers.Add(q);Call("Page","VK TURN");main.UpdateLayout();var scroll=All<ScrollViewer>(main).Single(v=>v.Name=="vkTurnSettingsScroll");
  var slider=All<Slider>(main).Single(v=>v.Name=="vkStreams_csqtt25");slider.ApplyTemplate();var track=(Track)slider.Template.FindName("PART_Track",slider);track.Value=slider.Maximum;Pump();Check(slider.Value==slider.Maximum&&VkTurnSettings.Load(root).Streams["csqtt25"]==100,"real themed slider track updates slider and encrypted worker setting");
  var content=(FrameworkElement)scroll.Content;foreach(var panel in All<StackPanel>(content).Where(v=>v.Orientation==Orientation.Vertical)){double bottom=-1;foreach(var child in panel.Children.OfType<FrameworkElement>().Where(v=>v.IsVisible&&v.ActualHeight>0)){var top=child.TranslatePoint(new Point(0,0),panel).Y;Check(top>=bottom-0.5,"vertical spacing: "+(child.Name.Length>0?child.Name:child.GetType().Name));bottom=top+child.ActualHeight;}}
  scroll.ScrollToTop();main.UpdateLayout();Save(main,Path.Combine(output,"vkturn-final-top.png"));scroll.ScrollToVerticalOffset(slider.TranslatePoint(new Point(0,0),content).Y-70);main.UpdateLayout();Save(main,Path.Combine(output,"vkturn-final-streams.png"));
  Dialog("VK TURN · "+q.Name,()=>{Call("VkTurnServerEditor",q);return true;},w=>{var mode=All<ComboBox>(w).Single(v=>v.Name=="vkQwdttMode");mode.SelectedIndex=2;var buttons=All<Button>(w).Where(b=>Convert.ToString(b.Content)=="Сохранить"||Convert.ToString(b.Content)=="Отмена").ToArray();Check(buttons.Length==2&&buttons.All(b=>b.TranslatePoint(new Point(0,0),w).Y+b.ActualHeight<=w.ActualHeight-8),"server editor actions anchored inside window without scrolling");Check(!All<CheckBox>(w).Any(v=>v.Name=="vkServerMasque"),"QWDTT editor has no irrelevant disabled WDTT MASQUE controls");Save(w,Path.Combine(output,"qwdtt-editor-final.png"));Click(w,"Сохранить");});
 }
 static int FreePort(){var l=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);l.Start();int p=((System.Net.IPEndPoint)l.LocalEndpoint).Port;l.Stop();return p;}
